+                hi[e] = fa_pv_tf32_rn(p);
+                lo[e] = fa_pv_tf32_rn(__fsub_rn(p, __uint_as_float(hi[e])));
+            }
+#pragma unroll
+            for (unsigned j = 0; j < NJ; ++j) {
+                const unsigned col = (warp * NJ + j) * 8 + lane / 4;
+                unsigned b[2] = {
+                    __float_as_uint(__bfloat162float(vtile[(k + lane % 4) * STRIDE + col])),
+                    __float_as_uint(__bfloat162float(vtile[(k + lane % 4 + 4) * STRIDE + col]))};
+                fa_pv_mma_tf32(acc[j], lo, b, acc[j]);
+                fa_pv_mma_tf32(acc[j], hi, b, acc[j]);
